static bool
evaluateSleep(Variables *variables, int argc, char **argv, int64 *usecs)
{
	const char *number;
	const char *unit;
	int64		usec;
	int64		multiplier;

	if (*argv[1] == ':')
	{
		if ((number = getVariable(variables, argv[1] + 1)) == NULL)
		{
			pg_log_error("%s: undefined variable \"%s\"", argv[0], argv[1] + 1);
			return false;
		}

		/*
		 * Raise an error if the value of a variable is not an integer, or is
		 * out of range.
		 */
		if (!strtoint64(number, true, &usec))
		{
			pg_log_error("%s: invalid sleep time \"%s\" for variable \"%s\"",
						 argv[0], number, argv[1] + 1);
			return false;
		}

else
{
	number = argv[1];

	/* the syntax has been checked, so only the range can be wrong here */
	if (!strtoint64(number, true, &usec))
	{
		pg_log_error("%s: invalid sleep time \"%s\"", argv[0], number);
		return false;
	}
}

/* seconds is the default unit */
unit = argc > 2 ? argv[2] : "s";

if (pg_strcasecmp(unit, "ms") == 0)
	multiplier = 1000;
else if (pg_strcasecmp(unit, "s") == 0)
	multiplier = 1000000;
else						/* "us", checked at parse time */
	multiplier = 1;

if (pg_mul_s64_overflow(usec, multiplier, usecs))
{
	pg_log_error("%s: sleep time \"%s\" is out of range for unit \"%s\"",
				 argv[0], number, unit);
	return false;
}

if (command->meta == META_SLEEP)
{
	int64		usec;

	/*
	 * A \sleep doesn't execute anything, we just get the delay from the
	 * argument, and enter the CSTATE_SLEEP state.  (The per-command
	 * latency will be recorded in CSTATE_SLEEP state, not here, after the
	 * delay has elapsed.)
	 */
	if (!evaluateSleep(&st->variables, argc, argv, &usec))
	{
		commandFailed(st, "sleep", "execution of meta-command failed");
		return CSTATE_ABORTED;
	}

	pg_time_now_lazy(now);
	/* an absurd delay saturates rather than wrapping to the past */
	if (pg_add_s64_overflow(*now, usec, &st->sleep_until))
		st->sleep_until = PG_INT64_MAX;
	return CSTATE_SLEEP;
}

case CSTATE_SLEEP:
	pg_time_now_lazy(&now);
	if (now < st->sleep_until)
		return;		/* still sleeping, nothing to do here */
	/* Else done sleeping. */
	st->state = CSTATE_END_COMMAND;
	break;

if (*c)
{
	if (my_command->argc == 2 && have_digit)
	{
		offsets[2] = offsets[1] + (c - my_command->argv[1]);
		my_command->argv[2] = pg_strdup(c);
		my_command->argc = 3;
		*c = '\0';
	}
